mapper.select:
SELECT id, owner_key, anonymous, updated_at FROM agent_conversation
WHERE owner_key = #{owner} AND NOT anonymous

    AND (updated_at, id) < (
        SELECT updated_at, id FROM agent_conversation WHERE id = #{cursor} AND owner_key = #{owner}
    )

ORDER BY updated_at DESC, id DESC LIMIT #{limit}

SELECT  FROM agent_turn
WHERE execution_id = #{id} AND conversation_id IN (
    SELECT id FROM agent_conversation WHERE owner_key = #{owner}
)
